test "S2 complete JSONTestSuite grammar and implementation policies" {
    for (cases) |case| {
        if (json.parse(json.Value, std.testing.allocator, case.input, .{ .reject_duplicates = false })) |owner| {
            var result = owner;
            defer result.deinit();
            if (!case.accept) {
                std.debug.print("unexpected acceptance: {s}\n", .{case.name});
                return error.TestUnexpectedResult;
            }
        } else |err| {
            if (case.accept) {
                std.debug.print("unexpected refusal: {s}: {s}\n", .{ case.name, @errorName(err) });
                return err;
            }
        }
    }
}
